/* ===================== BÀI 15 · So sánh, nhảy và vòng lặp ===================== */
/* Bài 15 · So sánh, nhảy và vòng lặp (AMTS-EMB-001-M04-L03, MC51-015) — sinh bởi tools/author/mcu8051/l15.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR15=[{"label":"Ví dụ: SJMP, JNZ và độ dời tương đối","code":"; Ví dụ 1: SJMP, JNZ và độ dời tương đối\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     A,#00H                  ; 0000H\n        SJMP    TIEP                    ; 0002H: nhảy qua lệnh kế\n        MOV     A,#0FFH                 ; 0004H: bị bỏ qua\nTIEP:   JNZ     XONG                    ; 0006H: A = 0 nên không nhảy\n        MOV     P1,#0FEH                ; 0008H: LED P1.0 sáng\nXONG:   SJMP    $                       ; 000BH\n        END\n","note":"SJMP TIEP có mã 80 02: lệnh kế tiếp ở 0004H, đích 0006H, độ dời +2. JNZ XONG có mã 70 03 (0008H + 3 = 000BH); A = 0 nên không nhảy và LED P1.0 sáng. Đổi lệnh đầu thành MOV A,#01H rồi chạy lại: JNZ nhảy, LED tắt.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Tổng 10 số bằng DJNZ","code":"; Ví dụ 2: tổng 10 + 9 + ... + 1 bằng DJNZ\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        CLR     A                       ; tổng = 0\n        MOV     R7,#10                  ; bộ đếm vòng\nLAP:    ADD     A,R7                    ; tổng = tổng + R7\n        DJNZ    R7,LAP                  ; R7 - 1, khác 0 thì lặp\n        MOV     30H,A                   ; lưu tổng\n        SJMP    $\n        END\n","note":"Đoán trước: tổng 10 + 9 + … + 1 = 55 = 37H. DJNZ R7,LAP có mã DF FD (độ dời −3, về lệnh ADD). Chu kỳ: 1 + 1 + 10 × (1 + 2) + 1 = 33 tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: CJNE so sánh và cờ CY","code":"; Ví dụ 3: CJNE so sánh và cờ CY\n; So A với 50H: bằng -> LED 0, lớn hơn -> LED 1,\n; nhỏ hơn -> LED 2 (LED sáng khi chân = 0).\n        ORG     0000H\n        MOV     A,#3AH                  ; thử đổi thành 50H, 60H\n        CJNE    A,#50H,KHAC             ; khác 50H thì nhảy\n        MOV     P1,#0FEH                ; A = 50H\n        SJMP    XONG\nKHAC:   JC      NHO                     ; CY = 1: A < 50H\n        MOV     P1,#0FDH                ; A > 50H\n        SJMP    XONG\nNHO:    MOV     P1,#0FBH                ; A < 50H\nXONG:   SJMP    $\n        END\n","note":"A = 3AH khác 50H nên CJNE nhảy tới KHAC và đặt CY = 1 (3AH < 50H); JC nhảy tới NHO: LED P1.2 sáng. Sửa 3AH thành 50H (LED P1.0) hoặc 60H (LED P1.1, CY = 0) rồi chạy lại.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: JBC và JB — nhảy theo một bit","code":"; Ví dụ 4: JBC, JB - nhảy theo một bit\n; Bit 00H là cờ \"có việc cần làm\".\n        ORG     0000H\n        SETB    00H                     ; bật cờ\n        JBC     00H,XULY                ; cờ = 1: xóa cờ rồi nhảy\n        MOV     P1,#0FEH                ; (bị bỏ qua)\nXULY:   JB      00H,XONG                ; cờ đã bị xóa: không nhảy\n        MOV     P1,#0FDH                ; LED P1.1 sáng\nXONG:   SJMP    $\n        END\n","note":"JBC 00H,XULY (mã 10 00 03): bit 00H = 1 nên nhảy và xóa luôn bit đó (ô 20H về 00H). JB 00H,XONG không nhảy vì bit đã 0, nên LED P1.1 sáng. Cả hai lệnh 3 byte, 2 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Vòng lặp lồng nhau tạo trễ","code":"; Ví dụ 5: hai vòng lặp lồng nhau tạo trễ\n; Chip: AT89S52. Đổi thạch anh 12 / 11,0592 MHz.\n        ORG     0000H\n        MOV     R6,#10                  ; vòng ngoài 10 lần\nNGOAI:  MOV     R7,#100                 ; vòng trong 100 lần\nTRONG:  DJNZ    R7,TRONG\n        DJNZ    R6,NGOAI\n        CPL     P1.0                    ; đánh dấu: hết thời gian trễ\n        SJMP    $\n        END\n","note":"Vòng trong 100 × 2 chu kỳ, vòng ngoài 10 lần: 1 + 10 × (1 + 200 + 2) + 1 = 2 032 chu kỳ tới SJMP $: 2 032 µs ở 12 MHz, khoảng 2 204,86 µs ở 11,0592 MHz. Đặt điểm dừng ở dòng DJNZ R6 để xem R7 về 0 sau mỗi vòng ngoài.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Vòng lặp đọc vượt biên mảng","code":"; Ví dụ 6 (bẫy): vòng lặp đọc vượt biên mảng\n; Mảng 4 byte 30H..33H; ô 34H là biến khác.\n        ORG     0000H\n        MOV     30H,#05H\n        MOV     31H,#07H\n        MOV     32H,#02H\n        MOV     33H,#09H\n        MOV     34H,#99H                ; không thuộc mảng\n        CLR     A\n        MOV     R0,#30H\nLAP:    ADD     A,@R0                   ; cộng phần tử\n        INC     R0\n        CJNE    R0,#35H,LAP             ; điều kiện dừng?\n        MOV     40H,A                   ; mong 17H\n        SJMP    $\n        END\n","note":"Mảng có 4 phần tử 30H–33H nhưng CJNE dừng khi R0 = 35H, nên vòng lặp chạy 5 lần và cộng cả ô 34H: 05 + 07 + 02 + 09 + 99H = B0H thay vì 17H. Sửa điều kiện thành CJNE R0,#34H,LAP.","dev":{"led":true},"fosc":12000000}];
const sim15=makeSim51(document.getElementById("m51-l15"),{id:"s15",presets:PR15,ram:256});
makeEx51(document.getElementById("ex-l15"),"l15",[{"t":"Đếm số byte bằng 0 trong dãy","d":"<p>Tám ô <code>30H<\/code>–<code>37H<\/code> chứa một dãy số. Đếm số ô có giá trị <code>00H<\/code> và ghi kết quả vào <code>40H<\/code>. Ô <code>38H<\/code> trở đi <b>không<\/b> thuộc dãy. Các ô 30H–38H giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H..37H = 00 05 00 07 00 09 01 02<\/code> → <code>40H = 03H<\/code>.<\/p>","start":"; Đếm số byte bằng 00H trong 8 ô 30H..37H, ghi vào 40H.\n        ORG     0000H\n        MOV     40H,#0                  ; bộ đếm = 0\n; viết vòng lặp duyệt 30H..37H ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":5,"0x32":0,"0x33":7,"0x34":0,"0x35":9,"0x36":1,"0x37":2,"0x38":0,"0x40":238}},"expect":{"iram":{"0x30":0,"0x31":5,"0x32":0,"0x33":7,"0x34":0,"0x35":9,"0x36":1,"0x37":2,"0x38":0,"0x40":3}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x38":0,"0x40":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x38":0,"0x40":8}}},{"setup":{"iram":{"0x30":17,"0x31":34,"0x32":51,"0x33":68,"0x34":85,"0x35":102,"0x36":119,"0x37":136,"0x38":0,"0x40":238}},"expect":{"iram":{"0x30":17,"0x31":34,"0x32":51,"0x33":68,"0x34":85,"0x35":102,"0x36":119,"0x37":136,"0x38":0,"0x40":0}}},{"setup":{"iram":{"0x30":1,"0x31":1,"0x32":1,"0x33":1,"0x34":1,"0x35":1,"0x36":1,"0x37":0,"0x38":5,"0x40":238}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":1,"0x33":1,"0x34":1,"0x35":1,"0x36":1,"0x37":0,"0x38":5,"0x40":1}}},{"setup":{"iram":{"0x30":0,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x38":0,"0x40":238}},"expect":{"iram":{"0x30":0,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x38":0,"0x40":1}}},{"setup":{"iram":{"0x30":128,"0x31":0,"0x32":1,"0x33":0,"0x34":254,"0x35":0,"0x36":127,"0x37":0,"0x38":0,"0x40":238}},"expect":{"iram":{"0x30":128,"0x31":0,"0x32":1,"0x33":0,"0x34":254,"0x35":0,"0x36":127,"0x37":0,"0x38":0,"0x40":4}}}]},"hints":["Dùng R0 làm con trỏ bắt đầu từ 30H và R7 làm bộ đếm vòng; mỗi vòng đọc MOV A,@R0 rồi tăng R0.","JNZ nhảy khi A khác 0, nên đặt lệnh đếm (INC 40H) ngay sau JNZ: chỉ chạy khi A = 0.","Đếm số vòng cẩn thận: dãy có đúng 8 phần tử. Bộ thử 3 bắt lỗi đọc thừa một ô, bộ thử 4 bắt lỗi đọc thiếu ô cuối."],"why":"8051 không có cờ Z: JZ, JNZ xét trực tiếp A. Vòng lặp chuẩn gồm con trỏ R0, bộ đếm R7 = số phần tử và DJNZ ở cuối. Đặt R7 = 7 sẽ bỏ sót ô 37H, R7 = 9 sẽ đếm cả ô 38H không thuộc dãy."},{"t":"Số lớn nhất và vị trí của nó","d":"<p>Code mẫu tìm số lớn nhất (không dấu) trong 8 ô <code>30H<\/code>–<code>37H<\/code> nhưng đọc vượt biên sang ô <code>38H<\/code> (không thuộc dãy) và chưa ghi vị trí. Sửa để: <code>40H<\/code> = số lớn nhất của dãy; <code>41H<\/code> = vị trí (0 … 7) của <b>lần xuất hiện đầu tiên<\/b> của số lớn nhất (30H là vị trí 0). Các ô 30H–3FH giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H..37H = 17 82 05 C4 60 01 33 44<\/code> → <code>40H = C4H, 41H = 03H<\/code>.<\/p>","start":"; Tìm số lớn nhất trong 8 byte 30H..37H -> 40H,\n; vị trí (0..7) của số lớn nhất đầu tiên -> 41H.\n; Code có lỗi vượt biên và chưa ghi 41H.\n        ORG     0000H\n        MOV     R0,#30H\n        MOV     A,@R0                   ; max tạm = 30H\n        MOV     R7,#8                   ; số lần so sánh?\nLAP:    INC     R0\n        MOV     B,@R0\n        CJNE    A,B,SS\nSS:     JNC     BO\n        MOV     A,B\nBO:     DJNZ    R7,LAP\n        MOV     40H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":23,"0x31":130,"0x32":5,"0x33":196,"0x34":96,"0x35":1,"0x36":51,"0x37":68,"0x38":0,"0x40":238,"0x41":238}},"expect":{"iram":{"0x30":23,"0x31":130,"0x32":5,"0x33":196,"0x34":96,"0x35":1,"0x36":51,"0x37":68,"0x38":0,"0x40":196,"0x41":3}}},{"setup":{"iram":{"0x30":16,"0x31":32,"0x32":48,"0x33":64,"0x34":80,"0x35":96,"0x36":112,"0x37":128,"0x38":255,"0x40":238,"0x41":238}},"expect":{"iram":{"0x30":16,"0x31":32,"0x32":48,"0x33":64,"0x34":80,"0x35":96,"0x36":112,"0x37":128,"0x38":255,"0x40":128,"0x41":7}}},{"setup":{"iram":{"0x30":240,"0x31":1,"0x32":2,"0x33":3,"0x34":4,"0x35":5,"0x36":6,"0x37":7,"0x38":255,"0x40":238,"0x41":238}},"expect":{"iram":{"0x30":240,"0x31":1,"0x32":2,"0x33":3,"0x34":4,"0x35":5,"0x36":6,"0x37":7,"0x38":255,"0x40":240,"0x41":0}}},{"setup":{"iram":{"0x30":85,"0x31":85,"0x32":85,"0x33":85,"0x34":85,"0x35":85,"0x36":85,"0x37":85,"0x38":255,"0x40":238,"0x41":238}},"expect":{"iram":{"0x30":85,"0x31":85,"0x32":85,"0x33":85,"0x34":85,"0x35":85,"0x36":85,"0x37":85,"0x38":255,"0x40":85,"0x41":0}}},{"setup":{"iram":{"0x30":1,"0x31":154,"0x32":2,"0x33":154,"0x34":3,"0x35":154,"0x36":4,"0x37":5,"0x38":0,"0x40":238,"0x41":238}},"expect":{"iram":{"0x30":1,"0x31":154,"0x32":2,"0x33":154,"0x34":3,"0x35":154,"0x36":4,"0x37":5,"0x38":0,"0x40":154,"0x41":1}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x38":1,"0x40":238,"0x41":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x38":1,"0x40":0,"0x41":0}}},{"setup":{"iram":{"0x30":127,"0x31":128,"0x32":0,"0x33":255,"0x34":254,"0x35":1,"0x36":255,"0x37":0,"0x38":255,"0x40":238,"0x41":238}},"expect":{"iram":{"0x30":127,"0x31":128,"0x32":0,"0x33":255,"0x34":254,"0x35":1,"0x36":255,"0x37":0,"0x38":255,"0x40":255,"0x41":3}}}]},"hints":["Phần tử đầu đã nằm trong A trước vòng lặp, nên 8 phần tử chỉ cần 7 lần so sánh. Code mẫu so 8 lần nên đọc tới 38H.","Khi tìm được max mới, ghi lại R0 (địa chỉ của nó) vào một ô, ví dụ MOV 41H,R0. Cuối chương trình đổi địa chỉ thành vị trí bằng cách trừ 30H.","Hai số bằng nhau thì giữ vị trí đầu tiên: CJNE đặt CY thế nào khi hai số bằng nhau? Đừng quên giá trị ban đầu của 41H."],"why":"Vòng lặp có n − 1 lần so sánh vì phần tử đầu là giá trị khởi tạo. Bộ thử 2 đặt FFH ở ô 38H nên code so 8 lần báo max = FFH. Vị trí lấy từ con trỏ R0 lúc cập nhật max, đổi ra 0…7 bằng CLR C và SUBB #30H; khởi tạo 41H = 30H cho trường hợp max ở ô đầu (bộ thử 3, 4, 6)."},{"t":"So sánh 16 bit không cần nhánh ≤ 10 chu kỳ","d":"<p>X = <code>31H:30H<\/code>, Y = <code>33H:32H<\/code> là hai số 16 bit không dấu (byte thấp ở địa chỉ thấp). Ghi <code>40H = 01H<\/code> nếu X &gt; Y, ngược lại <code>40H = 00H<\/code>. X, Y giữ nguyên. Code mẫu đúng nhưng dài 22 byte và nhiều nhánh. Viết lại để toàn chương trình chạy không quá <b>10 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>15 byte<\/b>.<\/p><p>Ví dụ: X = <code>1234H<\/code>, Y = <code>1199H<\/code> → <code>40H = 01H<\/code>.<\/p>","start":"; X = 31H:30H, Y = 33H:32H (không dấu, byte thấp trước)\n; 40H = 01H nếu X > Y, ngược lại 00H.\n; Chạy đúng nhưng dài: cần <= 10 chu kỳ, <= 15 byte.\n        ORG     0000H\n        MOV     40H,#00H                ; giả sử X <= Y\n        MOV     A,31H\n        CJNE    A,33H,KHAC              ; so byte cao\n        MOV     A,30H                   ; byte cao bằng: so byte thấp\n        CJNE    A,32H,KHAC\n        SJMP    XONG                    ; X = Y\nKHAC:   JC      XONG                    ; X < Y\n        MOV     40H,#01H                ; X > Y\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":52,"0x31":18,"0x32":153,"0x33":17,"0x40":238}},"expect":{"iram":{"0x30":52,"0x31":18,"0x32":153,"0x33":17,"0x40":1}}},{"setup":{"iram":{"0x30":52,"0x31":18,"0x32":52,"0x33":18,"0x40":238},"regs":{"PSW":128}},"expect":{"iram":{"0x30":52,"0x31":18,"0x32":52,"0x33":18,"0x40":0}}},{"setup":{"iram":{"0x30":53,"0x31":18,"0x32":52,"0x33":18,"0x40":238}},"expect":{"iram":{"0x30":53,"0x31":18,"0x32":52,"0x33":18,"0x40":1}}},{"setup":{"iram":{"0x30":51,"0x31":18,"0x32":52,"0x33":18,"0x40":238}},"expect":{"iram":{"0x30":51,"0x31":18,"0x32":52,"0x33":18,"0x40":0}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":255,"0x33":255,"0x40":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":255,"0x33":255,"0x40":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":254,"0x33":255,"0x40":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":254,"0x33":255,"0x40":1}}},{"setup":{"iram":{"0x30":0,"0x31":128,"0x32":255,"0x33":127,"0x40":238}},"expect":{"iram":{"0x30":0,"0x31":128,"0x32":255,"0x33":127,"0x40":1}}},{"setup":{"iram":{"0x30":255,"0x31":0,"0x32":0,"0x33":1,"0x40":238}},"expect":{"iram":{"0x30":255,"0x31":0,"0x32":0,"0x33":1,"0x40":0}}}],"maxCyc":10,"maxBytes":15},"hints":["Phép trừ cũng là phép so sánh: trừ 16 bit Y − X bằng CLR C và hai lệnh SUBB (byte thấp rồi byte cao). Sau đó CY = 1 đúng khi Y &lt; X, tức X &gt; Y.","Không cần giữ hiệu, chỉ cần cờ CY cuối cùng. Không cần lệnh nhảy nào.","Kết quả chính là cờ CY: đổi cờ thành byte 00H/01H mà không cần lệnh nhảy, như bài tập 1 của Bài 14."],"why":"SUBB nhiều byte cho cờ mượn CY của cả số 16 bit: CY = 1 khi số bị trừ nhỏ hơn số trừ (không dấu). Tính Y − X thì CY = 1 đúng khi X &gt; Y. CLR C, 4 lệnh đọc/trừ, CLR A, RLC A, ghi 40H: 8 chu kỳ + SJMP $ = 10, 15 byte; không có nhánh nên số chu kỳ như nhau với mọi dữ liệu. Bỏ CLR C thì trượt bộ thử 2: bộ thử này bắt đầu với CY = 1, giống khi đoạn code chạy ngay sau một phép toán khác để lại cờ nhớ."}]);

makeQuiz("quiz15","score15",[{"q": "Đoạn MOV A,#05H rồi DEC R5 (R5 = 1, sau lệnh R5 = 0) rồi JZ XONG. JZ có nhảy không?", "o": ["Có: kết quả của DEC R5 bằng 0 nên cờ Z = 1", "Có: JZ xét cờ CY", "Không: JZ xét A (đang bằng 05H), không xét R5", "Trình dịch báo lỗi vì JZ phải đi kèm CJNE"], "a": 2, "e": "8051 không có cờ Z. JZ, JNZ kiểm tra trực tiếp A. Muốn nhảy khi R5 = 0 thì dùng MOV A,R5 rồi JZ, hoặc DJNZ."}, {"q": "A = 3AH. Lệnh CJNE A,#50H,KHAC làm gì?", "o": ["Nhảy tới KHAC và đặt CY = 0", "Nhảy tới KHAC và đặt CY = 1", "Không nhảy, CY = 1", "Nhảy tới KHAC và đổi A thành 50H"], "a": 1, "e": "3AH ≠ 50H nên nhảy; 3AH < 50H (không dấu) nên CY = 1. CJNE không đổi A."}, {"q": "Đoạn MOV R6,#10 / NGOAI: MOV R7,#100 / TRONG: DJNZ R7,TRONG / DJNZ R6,NGOAI chạy bao nhiêu chu kỳ máy?", "o": ["2 000", "2 010", "2 031", "4 062"], "a": 2, "e": "1 (MOV R6) + 10 × [1 (MOV R7) + 100 × 2 (DJNZ trong) + 2 (DJNZ ngoài)] = 1 + 10 × 203 = 2 031. 2 000 là chỉ đếm vòng trong."}, {"q": "SJMP $ được dịch thành 80 FE. Byte FE nghĩa là gì?", "o": ["Địa chỉ tuyệt đối 00FEH", "Độ dời +254 tính từ đầu chương trình", "Mã lệnh “dừng CPU”", "Độ dời −2 tính từ địa chỉ lệnh kế tiếp, nên nhảy về chính lệnh SJMP"], "a": 3, "e": "Độ dời là số có dấu 8 bit: FEH = −2. Lệnh kế tiếp ở (địa chỉ SJMP + 2), cộng −2 thì về đúng địa chỉ SJMP. CPU vẫn chạy, chỉ lặp tại chỗ."}, {"q": "Đoạn MOV R7,#0 rồi LAP: DJNZ R7,LAP lặp bao nhiêu lần?", "o": ["256 lần", "0 lần", "1 lần", "255 lần"], "a": 0, "e": "DJNZ giảm trước rồi mới kiểm: 00H − 1 = FFH ≠ 0 nên lặp tiếp, tới khi về 0 sau 256 lần giảm."}]);

